SET local check_function_bodies = off;

DROP FUNCTION "api"."create_share_link"(uuid, text, text, text, uuid, timestamp WITH time zone);

DROP FUNCTION "api"."restore_version"(uuid);

DROP FUNCTION "better_supabase"."create_share_link"(uuid, text, text, text, uuid, timestamp WITH time zone);

DROP FUNCTION "better_supabase"."resolve_share_link"(text);

DROP FUNCTION "better_supabase"."restore_version"(uuid);

CREATE TABLE "better_supabase"."outbox_consumers" (
  "name"            text                     NOT NULL,
  "cursor_xid"      xid8                     NOT NULL DEFAULT '0'::xid8,
  "cursor_position" bigint                   NOT NULL DEFAULT 0,
  "types"           text[],
  "lease_owner"     text,
  "lease_until"     timestamp with time zone,
  "attempts"        integer                  NOT NULL DEFAULT 0,
  "last_error"      text,
  "retry_at"        timestamp with time zone,
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "outbox_consumers_pkey" PRIMARY KEY (name)
);

ALTER TABLE "better_supabase"."outbox_consumers"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."outbox_dead_letters" (
  "consumer" text                     NOT NULL,
  "position" bigint                   NOT NULL,
  "event_id" text                     NOT NULL,
  "type"     text                     NOT NULL,
  "event"    jsonb                    NOT NULL,
  "attempts" integer                  NOT NULL,
  "error"    text,
  "dead_at"  timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "outbox_dead_letters_pkey" PRIMARY KEY (consumer, "position")
);

ALTER TABLE "better_supabase"."outbox_dead_letters"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "better_supabase"."outbox_events" (
  "id"              uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "position"        bigint                   GENERATED ALWAYS AS IDENTITY NOT NULL,
  "type"            text                     NOT NULL,
  "source"          text,
  "subject"         text,
  "organization_id" uuid,
  "key"             text,
  "payload"         jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "actor_id"        uuid,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "xid"             xid8                     NOT NULL DEFAULT pg_current_xact_id(),
  CONSTRAINT "outbox_events_pkey" PRIMARY KEY (id),
  CONSTRAINT "outbox_events_position_key" UNIQUE ("position")
);

ALTER TABLE "better_supabase"."outbox_events"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "better_supabase"."share_links"
  ADD COLUMN "use_count" integer NOT NULL DEFAULT 0;

ALTER TABLE "public"."projects"
  ADD COLUMN "internal_notes" text;

CREATE OR REPLACE FUNCTION api.create_share_link (
