    event_type => 'announcement.deleted',
    category => 'configuration',
    target_type => 'announcement',
    record_id => delete_announcement.id::text,
    metadata => jsonb_build_object('announcementId', delete_announcement.id)
  );
  end if;
  return v_count > 0;
end;
$function$;

CREATE OR REPLACE FUNCTION better_supabase.delete_calendar_event (
  event_id uuid
)
  RETURNS boolean
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO ''
  AS $function$
#variable_conflict use_column
declare
  v_id uuid := delete_calendar_event.event_id;
